insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"articles_a_an_q01_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q01_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q02_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q02_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q03_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q03_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q04_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q04_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q05_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q05_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q06_finish","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}},{"key":"articles_a_an_q06_start","speaker_external_id":"Fisherman","source_path":"_registry\\dialogues\\articles_a_an.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"articles_a_an_q01_finish","locale":"he","line_order":0,"content":"יפה מאוד. כשאומרים את a נכון, הרשת מחזיקה חזק.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_finish","locale":"he","line_order":1,"content":"אבל לפעמים היא נקרעת בלי שום סיבה. יש לי סוד שעוד לא סיפרתי לאף אחד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_finish","locale":"he","line_order":2,"content":"תחזרו אליי, ואני אספר לכם.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_start","locale":"he","line_order":0,"content":"שלום. אני נמו Nemo, הדייג של המפרץ. כולם פה קוראים לי נמו בלי הרשת.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_start","locale":"he","line_order":1,"content":"הבוקר עוד רשת שלי נקרעה. זאת כבר הרשת השלישית השבוע.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_start","locale":"he","line_order":2,"content":"הרשתות שלי מיוחדות. הן מחזיקות מילים באנגלית, ובמיוחד מילה אחת קטנה מאוד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_start","locale":"he","line_order":3,"content":"a = אחד או אחת. שמים אותה לפני שם של דבר אחד. a shell = צדף אחד, a crab = סרטן אחד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q01_start","locale":"he","line_order":4,"content":"התיבה ליד המים מלאה במילים של הים. בואו נתחיל משם.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_finish","locale":"he","line_order":0,"content":"מצאתם את AN. כבר שנים לא ראיתי אותו שוחה ככה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_finish","locale":"he","line_order":1,"content":"אבל הסערה האחרונה בלבלה את כל המפרץ. בואו נבדוק מה קרה בשוק הדגים.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_start","locale":"he","line_order":0,"content":"כשהייתי ילד נפלתי מהסירה של אבא שלי בסערה גדולה, ושקעתי במים.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_start","locale":"he","line_order":1,"content":"מלכת הים הצילה אותי. בתמורה הבטחתי לה לשמור על שני דגים קטנים ותאומים.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_start","locale":"he","line_order":2,"content":"לאחד קוראים A ולשני קוראים AN. ל־AN יש זנב נוסף, האות n.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_start","locale":"he","line_order":3,"content":"באנגלית יש חמש אותיות תנועה: a, e, i, o, u. אות תנועה = vowel.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q02_start","locale":"he","line_order":4,"content":"כשהמילה הבאה מתחילה באות תנועה, שמים an במקום a. an ant = נמלה אחת, an owl = ינשוף אחד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_finish","locale":"he","line_order":0,"content":"עכשיו השוק נראה כמו שצריך, והתאומים שוחים בשקט.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_finish","locale":"he","line_order":1,"content":"רגע, מה זה על החוף? בקבוק עם מכתב בפנים. תחזרו אליי ונפתח אותו יחד.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_start","locale":"he","line_order":0,"content":"תראו את השלטים בשוק. מישהו כתב אותם בזמן הסערה, והכול התבלבל.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_start","locale":"he","line_order":1,"content":"ליד הדגים כתוב an, וליד הביצים כתוב a. בגלל שלטים כאלה הרשת שלי נקרעת.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_start","locale":"he","line_order":2,"content":"הסוד פשוט: מסתכלים על האות הראשונה של המילה שבאה אחרי.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q03_start","locale":"he","line_order":3,"content":"בואו נסדר את השלטים מחדש.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q04_finish","locale":"he","line_order":0,"content":"עכשיו אפשר לקרוא הכול. מלכת הים כותבת שהתאומים מחכים ליד הסלעים.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q04_finish","locale":"he","line_order":1,"content":"והיא מזהירה שמילת תיאור יכולה לבלבל אותם. תחזרו אליי, ונלך לבדוק.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q04_start","locale":"he","line_order":0,"content":"המכתב הזה ממלכת הים. אני מכיר את כתב היד שלה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q04_start","locale":"he","line_order":1,"content":"המים מחקו ממנו את המילים הקטנות, ובלי a ו־an אי אפשר להבין מה היא רוצה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q04_start","locale":"he","line_order":2,"content":"בואו נבנה מחדש את המשפטים שלה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_finish","locale":"he","line_order":0,"content":"התאומים שוחים שוב זה ליד זה. עכשיו הם יודעים מי הולך לפני כל מילה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_finish","locale":"he","line_order":1,"content":"מחר נארוג יחד רשת חדשה. תחזרו אליי.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_start","locale":"he","line_order":0,"content":"זוכרים את מילות התיאור? big = גדול, old = ישן, small = קטן.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_start","locale":"he","line_order":1,"content":"לפעמים מילת תיאור נכנסת בין a או an לבין השם של הדבר.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_start","locale":"he","line_order":2,"content":"הכלל החשוב: רק המילה שבאה מיד אחרי a או an מחליטה, לא המילה שבסוף.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q05_start","locale":"he","line_order":3,"content":"an ant = נמלה, אבל a big ant = נמלה גדולה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_finish","locale":"he","line_order":0,"content":"תראו. קשרתי את אבן החן לרשת, והיא לא נקרעת.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_finish","locale":"he","line_order":1,"content":"מהיום אני כבר לא נמו בלי הרשת. אני נמו של הרשת.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_finish","locale":"he","line_order":2,"content":"קחו את המטבעות האלה כתודה. בזכותכם התאומים A ו־AN חזרו הביתה.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_start","locale":"he","line_order":0,"content":"הגיע הזמן. היום אני אורג את הרשת שמלכת הים ביקשה ממני לפני הרבה שנים.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_start","locale":"he","line_order":1,"content":"כל משפט נכון הוא קשר חזק ברשת. משפט עם טעות הוא חור.","line_format":"plain_text"},{"dialogue_key":"articles_a_an_q06_start","locale":"he","line_order":2,"content":"בסוף מלכת הים תשלח לנו את אבן החן שלה, והיא תחזיק את הרשת לתמיד.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
